-- vs_route_town_vs_enemy_formation_menu: the rival's side of the Chronicle VS screen (graft.toml). The retail
-- SetFormation runs as it is, then VRFW_VSF.Apply on the rival's members. A rival without a team row (a1 == 0: the
-- retail placeholder formation, 20 dummy cards) stays retail.
do
  -- VRFW vs small format: shared helpers (both VS menus run in their own Lua state; definitions only)
  VRFW_VSF = VRFW_VSF or {}
  VRFW_VSF.LOG = 3661580131                 -- (loader log; pcall: absent without the Lua bridge)
  VRFW_VSF.SLOTS = 19                       -- card slots: 0-10 field, 11-15 bench, 16-18 support (19 = coach layer)
  VRFW_VSF.COACH = 19
  VRFW_VSF.LEADER_BLANK = 2290394976        -- team00_01_p1_chara_card_blank_for_leader
  function VRFW_VSF.log(...)
    pcall(funcLuaCommand, VRFW_VSF.LOG, "vs small format:", ...)
  end
  local function hide(layer, i)
    if type(layer) == "number" and funcLuaMenuCommand(262659071, layer, i) == true then
      funcLuaMenuCommand(711242136, layer, i, false)
    end
  end
  -- used: {[position] = true} of the drawn team's members (positions as the retail screen draws them). Fewer than 11
  -- field members = a small format: hide every card + blank frame without a member, and the coach card + frame when
  -- the team has no coach. 11 field members (or none read): the retail screen as it is.
  function VRFW_VSF.Apply(used, cards, blanks, leader, leader_blank, where)
    local field = 0
    for p = 0, 10 do
      if used[p] then
        field = field + 1
      end
    end
    if field == 0 or field >= 11 then
      return
    end
    local n = VRFW_VSF.SLOTS
    local made = funcLuaMenuCommand(1175615627, blanks)
    if type(made) == "number" and made > n then
      n = made
    end
    local hidden = 0
    for i = 0, n - 1 do
      if not used[i] then
        hide(cards, i)
        hide(blanks, i)
        hidden = hidden + 1
      end
    end
    local coach = used[VRFW_VSF.COACH] == true
    if not coach then
      hide(leader, 0)
      hide(leader_blank or VRFW_VSF.LEADER_BLANK, 0)
    end
    VRFW_VSF.log(where, "field members", field, "empty slots hidden", hidden, "coach", coach and "shown" or "hidden")
  end
  local vrfw_vsf_set_formation = SetFormation
  function SetFormation(a1, a2, a3, a4, a5, a6, a7, a8, ...)
    local r = table.pack(vrfw_vsf_set_formation(a1, a2, a3, a4, a5, a6, a7, a8, ...))
    if type(a1) == "number" and a1 ~= 0 then
      local used = {}
      local okN, num = funcLuaCommand(2151743654, a1, 8)
      for k = 0, ((okN and type(num) == "number") and num or 0) - 1 do
        local ok, _, p = GetTeamMemberInfo(a1, k, a2, a3)
        if ok and type(p) == "number" and p >= 0 and p <= 19 then
          used[p] = true
        end
      end
      VRFW_VSF.Apply(used, a5, a6, a7, a8, "rival team row")
    end
    return table.unpack(r, 1, r.n)
  end
end
